using System;using System.IO;using System.Linq;using System.Text;
namespace GearLab {public static class Industrial66Tests {
 public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();int count=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception(name);count++;log.AppendLine("PASS "+name);};try{
  var d=IndustrialRobot66.Create();check(d.Validate().Count==0,"independent engineering preset validates");check(d.Joints.Count==6,"six engineering axes, no game rig");check(d.Joints.All(j=>j.GeneratedBody==null&&j.BodyGenerator.IndustrialDesign),"preset contains parameters, not an imported model");
  check(d.Joints.All(j=>!j.BodyGenerator.BlenderDesign&&j.BodyGenerator.Connected&&j.BodyGenerator.ReferenceDesign),"industrial geometry uses mechanical interfaces");check(d.Joints.Last().Payload==.3,"300 g payload");
  check(d.Joints.All(j=>j.MotorFrame==42.3&&j.MotorShaft==5&&j.MotorLength==44),"NEMA17 envelope is independent of visual example");check(d.Joints.All(j=>j.MotorTorque==0&&j.MotorMass==.29),"unknown working torque is not invented");
  var fk=RobotKinematics.Evaluate(d,0,false);check(Math.Abs(fk[d.Joints.Last().Id].Tip.Z-1000)<1e-8,"one metre nominal vertical kinematic height");
  var high=IndustrialRobot66.Create(1200,.5);var hk=RobotKinematics.Evaluate(high,0,false);check(Math.Abs(hk[high.Joints.Last().Id].Tip.Z-1200)<1e-8,"height parameter changes link dimensions");check(high.Joints.All(j=>j.MotorFrame==42.3&&j.BearingOuter==d.Find(j.Id).BearingOuter),"scaling the arm does not scale motors and purchased bearings");
  string json=d.Serialize();check(!json.Contains("author-manipulator")&&!json.Contains("SourceSHA")&&!json.Contains("Preview\":"),"no baked game geometry or source metadata in project");check(RobotDocument.Parse(json).Joints.Count==6,"engineering project roundtrip");d.Save(Path.Combine(folder,"Industrial_parameters.robot.json"));
  var j2=d.Joints[1];string before=ProceduralBodySpec.Fingerprint(d,j2,j2.BodyGenerator);j2.EndZ+=20;check(before!=ProceduralBodySpec.Fingerprint(d,j2,j2.BodyGenerator),"link length invalidates real CAD");j2.EndZ-=20;
  foreach(string property in new[]{"FrameWall","SkinWall","Clearance"}){var copy=d.Clone();var c=copy.Joints[1];var p=typeof(ProceduralBodySettings).GetProperty(property);p.SetValue(c.BodyGenerator,(double)p.GetValue(c.BodyGenerator,null)+.1,null);check(before!=ProceduralBodySpec.Fingerprint(copy,c,c.BodyGenerator),property+" invalidates real CAD");}
  foreach(string property in new[]{"MotorLength","MotorShaft","BearingOuter","BearingWidth","Fit"}){var copy=d.Clone();var c=copy.Joints[1];var p=typeof(RobotJoint).GetProperty(property);p.SetValue(c,(double)p.GetValue(c,null)+.1,null);check(before!=ProceduralBodySpec.Fingerprint(copy,c,c.BodyGenerator),property+" invalidates mounting geometry");}
  var load=d.Clone();load.Joints.Last().Payload=.6;check(before!=ProceduralBodySpec.Fingerprint(load,load.Joints[1],load.Joints[1].BodyGenerator),"payload invalidates structural sizing");
  foreach(string name in new[]{"Robot1_800mm","SixAxis_Connected"}){string root=Path.GetDirectoryName(System.Windows.Forms.Application.ExecutablePath);string file=Path.Combine(root,"examples",name+".robot.json");if(!File.Exists(file))file=Path.Combine(Path.GetDirectoryName(root),"examples",name+".robot.json");var old=RobotDocument.Parse(File.ReadAllText(file));foreach(var j in old.Joints)check(j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(old,j,j.BodyGenerator),"legacy native cache unchanged: "+name+" / "+j.Name);}
  File.WriteAllText(Path.Combine(folder,"industrial66-results.txt"),log+"PASS "+count+" assertions",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"industrial66-error.txt"),log+ex.ToString(),Encoding.UTF8);return 1;}}
}}
